arguments.content:
pub enum Msg {
    Ping,
}

pub const VERSION: u8 = 1;

pub fn decode(bytes: &str) -> Result<Msg, String> {
    let body = bytes.trim();
    if body == "ping" {
        return Ok(Msg::Ping);
    }

    let compact: String = body.chars().filter(|ch| !ch.is_whitespace()).collect();
    if compact == format!(r#"{{"version":{},"type":"ping"}}"#, VERSION)
        || compact == format!(r#"{{"type":"ping","version":{}}}"#, VERSION)
    {
        return Ok(Msg::Ping);
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!(r#"{{"version":{},"type":"ping"}}"#, VERSION),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg, VERSION};

    #[test]
    fn decodes_versioned_ping() {
        assert!(matches!(
            decode(r#"{ "version": 1, "type": "ping" }"#),
            Ok(Msg::Ping)
        ));
        assert!(matches!(
            decode(r#"{ "type": "ping", "version": 1 }"#),
            Ok(Msg::Ping)
        ));
    }

    #[test]
    fn encodes_versioned_ping() {
        assert_eq!(encode(&Msg::Ping), format!(r#"{{"version":{},"type":"ping"}}"#, VERSION));
    }

    #[test]
    fn rejects_unknown_bodies() {
        assert!(decode("not-a-ping").is_err());
        assert!(decode(r#"{ "version": 2, "type": "ping" }"#).is_err());
    }
}

